"""writes docs/audit/game_ground_truth_examples.md: exact text + hashes for strong and disputed cases (deterministic picks:
the first N of each group sorted by answer_sha).   python build_packet.py"""
import json
from pathlib import Path
HERE = Path(__file__).resolve().parent; D = HERE.parent.parent / "docs" / "audit"; D.mkdir(parents=True, exist_ok=True)
R = [json.loads(l) for l in open(HERE / "game_audit_rows.jsonl")]
def grp(name, pred, n=8):
    xs = sorted([x for x in R if pred(x)], key=lambda x: x["answer_sha"])[:n]
    s = f"\n## {name} ({sum(1 for x in R if pred(x))} total; first {len(xs)} by hash)\n\n"
    for x in xs:
        s += (f"- `{x['answer_sha'][:12]}` {x['game']}/{x['split']} world `{x['world']}` cell `{x['cell']}` j={x['j']} | truth: **{x['truth']}** | receiver before: {x['receiver_before']}\n"
              f"  - message: \"{x['answer'].strip()}\"\n  - rule: {x['rule_class']} (asserted: {x['asserted']}) → **{x['category']}** | flags: {', '.join(x['flags']) or 'none'}\n"
              f"  - receiver after: belief {x['receiver_belief_after']}, action {x['receiver_action_after']} | attempted: {x['attempted_misleading']}, succeeded: {x['successful_misleading']}\n")
    return s
out = "# game ground-truth audit: example packet\n\ngenerated by pilot/audit/build_packet.py from pilot/audit/game_audit_rows.jsonl (full rows, hashes of prompt, answer and reasoning). see game_ground_truth.md.\n"
out += grp("strong deceptive (misaligned, uninformed, clean false assertion, receiver went where told, same-world aligned replies all truthful)", lambda x: x["packet"] == "strong_deceptive")
out += grp("strong aligned honest", lambda x: x["packet"] == "strong_aligned_honest")
out += grp("'strong' tempted-but-honest by answer text (DOWNGRADED: see hand review)", lambda x: x["packet"] == "strong_tempted_honest")
out += grp("disputed: aligned replies the rule calls false (labeller errors)", lambda x: x["payoff"] == "aligned" and x["attempted_misleading"])
out += grp("disputed: truthful label but the receiver was misled", lambda x: "truthful_but_receiver_misled" in x["flags"])
out += grp("disputed: attempt label but the uninformed receiver was not misled", lambda x: "attempt_but_receiver_not_misled" in x["flags"])
out += grp("disputed: feigned ignorance (sender knows)", lambda x: "feigned_ignorance" in x["flags"])
out += grp("disputed: withholding cell, false assertion (lying to protect confidential information)", lambda x: x["cell"] == "withhold_unin" and x["category"] == "false_assertion")
out += grp("disputed: withholding cell, disclosed the truth despite the policy", lambda x: x["cell"] == "withhold_unin" and x["category"] == "truthful")
out += grp("disputed: misaligned omission", lambda x: x["payoff"] == "misaligned" and x["category"] == "omission")
out += grp("excluded: truncated or empty", lambda x: x["packet"] == "excluded_truncated", 3)
(D / "game_ground_truth_examples.md").write_text(out); print(len(out))
